import { defineCollection } from 'astro:content';
import { glob } from 'astro/loaders';
import { z } from 'astro/zod';

// Generated by scripts/fetch-content.mjs from the published manifest (see src/content/manifest.schema.json).
// Image fields hold paths relative to the JSON file, so image() resolves them to ImageMetadata.
const projects = defineCollection({
  loader: glob({ pattern: '*.json', base: './src/content/projects' }),
  schema: ({ image }) =>
    z.object({
      id: z.string(),
      slug: z.string(),
      title: z.string(),
      seoTitle: z.string().nullable(),
      metaDescription: z.string(),
      summary: z.string(),
      bodyMarkdown: z.string(),
      serviceSlug: z.string(),
      townSlug: z.string(),
      townName: z.string(),
      completedOn: z.string().nullable(),
      publishedAt: z.coerce.date(),
      updatedAt: z.coerce.date(),
      featured: z.boolean(),
      cover: z.string(),
      ogImage: image(),
      photos: z
        .array(
          z.object({
            id: z.string(),
            role: z.enum(['before', 'after', 'progress', 'detail']),
            sortOrder: z.number().int(),
            altText: z.string(),
            caption: z.string().nullable().optional(),
            fileSlug: z.string(),
            dominantColor: z.string().nullable().optional(),
            focal: z.object({ x: z.number(), y: z.number() }).nullable().optional(),
            renditions: z.object({ master: image(), card4x3: image(), hero16x9: image() }),
          }),
        )
        .min(1),
    }),
});

export const collections = { projects };
